def show(path):
    return subprocess.run(["git","show",f"HEAD:{path}"], cwd=root, capture_output=True).stdout.decode()

def read(path):
    return open(os.path.join(root,path),encoding="utf-8").read()

def report(label, old, new):
    ho, hn = headings(old), headings(new)
    print(f"\n==== {label} old {len(ho)} new {len(hn)} ====")
    # sequence of heading texts
    so=[h[2] for h in ho]
    sn=[h[2] for h in hn]
    sm=difflib.SequenceMatcher(a=so, b=sn)
    for tag,i1,i2,j1,j2 in sm.get_opcodes():
        if tag=="equal":
            continue
        print(f"  {tag} old[{i1}:{i2}] new[{j1}:{j2}]")
        for h in ho[i1:i2]:
            print(f"    - L{h[0]} {'#'*h[1]} {h[2][:100]}")
        for h in hn[j1:j2]:
            print(f"    + L{h[0]} {'#'*h[1]} {h[2][:100]}")

