import { createMarkdownRenderer } from "/home/vostrikov/projects/packages/vaulter/node_modules/vitepress/dist/node/index.js"
import fs from "node:fs"
import path from "node:path"

const root = "/home/vostrikov/projects/packages/vaulter"
const md = await createMarkdownRenderer(root+"/docs", { cleanUrls: true }, root+"/docs")

function walk(dir, acc=[]) {
  for (const ent of fs.readdirSync(dir, {withFileTypes:true})) {
    if (ent.name === "node_modules" || ent.name === ".vitepress" || ent.name === "plan") continue
    const p = path.join(dir, ent.name)
    if (ent.isDirectory()) walk(p, acc)
    else if (ent.name.endsWith(".md")) acc.push(p)
  }
  return acc
}
const files = walk(root+"/docs")
const ids = new Map()
for (const file of files) {
  const src = fs.readFileSync(file, "utf8")
  const env = {}
  const html = md.render(src, env)
  const found = new Set()
  for (const m of html.matchAll(/\sid="([^"]+)"/g)) found.add(m[1])
  // also heading anchors specifically
  ids.set(file, found)
}

// extract links the php checker would see: skip fences and inline code, match ]( and href="
function visible(text) {
  const lines = text.split("\n")
  let fence = null
  const out = []
  for (const line of lines) {
    const m = line.match(/^\s*(```+|~~~+)/)
    if (m) {
      if (fence === null) fence = m[1][0]
      else if (m[1][0] === fence) fence = null
      out.push("")
      continue
    }
    out.push(fence ? "" : line)
  }
  return out.join("\n").replace(/`[^`\n]*`/g, m => " ".repeat(m.length))
}
function resolve(target, from) {
  const [pathPart, anchor] = (() => {
    const i = target.indexOf("#")
    return i < 0 ? [target, null] : [target.slice(0,i), decodeURIComponent(target.slice(i+1))]
  })()
  const clean = pathPart.split("?")[0]
  if (clean === "") return { file: from, anchor }
  let base
  if (clean.startsWith("/")) base = path.join(root, "docs", clean)
  else base = path.resolve(path.dirname(from), clean)
  const cands = [base, base+".md", base.replace(/\/$/,"")+"/index.md"]
  for (const c of cands) if (fs.existsSync(c) && fs.statSync(c).isFile()) return { file: c, anchor }
  return { file: null, anchor }
}

const misses = []
let checked = 0
for (const file of files) {
  const text = visible(fs.readFileSync(file,"utf8"))
  const lines = text.split("\n")
  lines.forEach((line, idx) => {
    const targets = []
    for (const m of line.matchAll(/\]\(\s*<?([^)\s>]+)>?(?:\s+"[^"]*")?\s*\)/g)) targets.push(m[1])
    for (const m of line.matchAll(/<a\s[^>]*href="([^"]+)"/gi)) targets.push(m[1])
    for (const target of targets) {
      if (/^([a-z][a-z0-9+.-]*:|\/\/)/i.test(target)) continue
      checked++
      const dest = resolve(target, file)
      if (!dest.anchor || dest.file === null) continue
      if (!dest.file.endsWith(".md")) continue
      const set = ids.get(dest.file)
      if (!set) continue
      if (!set.has(dest.anchor)) {
        misses.push(`${path.relative(root,file)}:${idx+1}: #${dest.anchor} not in vitepress ids of ${path.relative(root,dest.file)} (target ${target})`)
      }
    }
  })
}
console.log("checked", checked, "vitepress-missing anchors", misses.length)
for (const m of misses.slice(0, 40)) console.log(m)
if (misses.length > 40) console.log("...")
